\copy (SELECT q.id::text AS id, q.subject_area, upper(trim(q.correct_answer)) AS key, CASE WHEN q.pipeline_metadata::jsonb->>'blind_solve_wave' LIKE 'poolA_w%' THEN 'promote' ELSE 'lowconf' END AS srcset, q.question_text AS q, q.option_a oa, q.option_b ob, q.option_c oc, q.option_d od, q.option_e oe FROM question_bank q WHERE q.pipeline_metadata::jsonb->>'blind_solve_wave' LIKE 'poolA_w%' OR q.pipeline_metadata::jsonb->>'poolA_cat'='lowconf') TO 'C:/Users/husey/kiro2/backend/scripts/quality/_poolA_retag/audit_master.csv' WITH (FORMAT csv, HEADER true);
